function pascal(s){
  return String(s).replace(/[_\-\s]+(.)?/g,function(_,c){return c?c.toUpperCase():'';})
                  .replace(/^(.)/,function(_,c){return c.toUpperCase();});
}
function inferTs(val,key,ints){
