  var t=typeof val;
  if(t==='number') return 'number';
  if(t==='boolean') return 'boolean';
  if(t==='string') return 'string';
  if(t==='object'){ var name=pascal(key); buildTs(val,name,ints); return name; }
  return 'any';
}
function buildTs(obj,name,ints){
  var lines=['export interface '+name+' {'];
  for(var k in obj){ if(!Object.prototype.hasOwnProperty.call(obj,k)) continue;
    lines.push('  '+k+': '+inferTs(obj[k],k,ints)+';'); }
  lines.push('}'); ints.push(lines.join('\n'));
